#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int stock[5] = {0};
    int price[5] = {10, 20, 30, 40, 50};
    int revenue = 0;
    for (int i = 1; i < argc; i += 3) {
        char *command = argv[i];
        int sku = atoi(argv[i + 1]);
        int qty = atoi(argv[i + 2]);
        if (strcmp(command, "S") == 0) {
            if (stock[sku] >= qty) {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%d qty=%d revenue+=%d\n", sku, qty, price[sku] * qty);
            } else {
                printf("INSUFFICIENT_STOCK sku=%d\n", sku);
            }
        } else if (strcmp(command, "R") == 0) {
            stock[sku] += qty;
            printf("RESTOCK sku=%d qty=%d\n", sku, qty);
        }
    }
    printf("FINAL stock=");
    for (int i = 0; i < 5; i++) {
        printf("%d", stock[i]);
        if (i < 4) printf(",");
    }
    printf(" revenue=%d\n", revenue);
    return 0;
}
